import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} invoice
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Normalize and validate customer
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate date format and reality
  const dateRegex = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = dateRegex.exec(issueDate);
  if (!match) return fail('DATE_INVALID');
  const [, year, month, day] = match;
  const date = new Date(issueDate + 'T00:00:00Z');
  if (isNaN(date.getTime())) return fail('DATE_INVALID');
  // Validate that the date components match (to catch invalid dates like 2026-02-30)
  if (
    date.getUTCFullYear() !== Number(year) ||
    date.getUTCMonth() + 1 !== Number(month) ||
    date.getUTCDate() !== Number(day)
  ) {
    return fail('DATE_INVALID');
  }

  // Validate lines array
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Process lines
  const customer = customerResult.value;
  const processedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discountPercent if provided
    if (line.discountPercent !== undefined) {
      if (typeof line.discountPercent !== 'number' || line.discountPercent < 0 || line.discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
    }

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const processedLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Apply discount: line's own discountPercent wins, otherwise use tier discount
    if (line.discountPercent !== undefined) {
      processedLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
      if (tierDiscount > 0) {
        processedLine.discountPercent = tierDiscount;
      }
    }

    processedLines.push(processedLine);
  }

  const invoice = {
    customerId,
    issueDate,
    status: 'draft',
    lines: processedLines,
  };

  return ok(invoice);
}

/**
 * Calculate the total amount for a single invoice line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate subtotal, discount, VAT and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let totalDiscount = 0;
  let totalVat = 0;

  for (const line of invoice.lines) {
    const lineAmount = lineTotal(line);
    subtotal += lineAmount;

    // Calculate discount
    let lineDiscount = 0;
    if (line.discountPercent) {
      lineDiscount = roundCents((lineAmount * line.discountPercent) / 100);
      totalDiscount += lineDiscount;
    }

    // Calculate VAT on amount after discount
    const lineAmountAfterDiscount = lineAmount - lineDiscount;
    const lineVat = roundCents((lineAmountAfterDiscount * line.vatRate) / 100);
    totalVat += lineVat;
  }

  const total = Math.max(0, subtotal - totalDiscount + totalVat);
  return { subtotal, discount: totalDiscount, vat: totalVat, total };
}

/**
 * Add a line to an invoice (or increase qty if SKU already exists).
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  if (discountPercent !== undefined) {
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  const customer = customerResult.ok ? customerResult.value : null;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex !== -1) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Apply discount: line's own discountPercent wins, otherwise use tier discount
    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    } else if (customer) {
      const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
      if (tierDiscount > 0) {
        newLine.discountPercent = tierDiscount;
      }
    }

    newLines.push(newLine);
  }

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Issue an invoice (change status to 'issued' and assign a number).
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Array of existing invoice numbers
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const newInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };

  return ok(newInvoice);
}

